Here's the XAML and ViewModel setup:

### XAML

```xml
<RefreshView IsRefreshing="{Binding IsRefreshing}"
             Command="{Binding RefreshCommand}">
    <CollectionView ItemsSource="{Binding Items}"
                    SelectionMode="Single"
                    SelectedItem="{Binding CurrentItem, Mode=TwoWay}"
                    SelectionChangedCommand="{Binding ItemSelectedCommand}">
        <CollectionView.ItemTemplate>
            <DataTemplate x:DataType="models:Item">
                <Grid Padding="12" ColumnDefinitions="48,*">
                    <Image Source="{Binding Icon}"
                           WidthRequest="40" HeightRequest="40" />
                    <Label Grid.Column="1"
                           Text="{Binding Name}"
                           VerticalOptions="Center" />
                </Grid>
            </DataTemplate>
        </CollectionView.ItemTemplate>
    </CollectionView>
</RefreshView>
```

### ViewModel Bindings

```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private ObservableCollection<Item> items = new();

    [ObservableProperty]
    private Item? currentItem;

    [ObservableProperty]
    private bool isRefreshing;

    // Pull-to-refresh: reloads data, then sets IsRefreshing = false
    [RelayCommand]
    private async Task RefreshAsync()
    {
        var data = await _api.GetItemsAsync();
        Items = new ObservableCollection<Item>(data);
        IsRefreshing = false;
    }

    // Selection: navigates to detail, then clears selection
    [RelayCommand]
    private async Task ItemSelectedAsync()
    {
        if (CurrentItem is null) return;
        await _nav.GoToAsync("DetailPage", CurrentItem);
        CurrentItem = null; // clear so the same item can be re-selected
    }
}
```

### Key points

| Binding | Purpose |
|---|---|
| `IsRefreshing` (TwoWay) | Controls the refresh spinner; set `false` when done |
| `Command` on RefreshView | Fires your API reload logic |
| `SelectedItem` (TwoWay) | Tracks the tapped item |
| `SelectionChangedCommand` | Triggers navigation on selection |

**Important:** Use `ObservableCollection<T>` (not `List<T>`) so the UI updates automatically. Always set `CurrentItem = null` after navigating so the user can re-select the same item. Set `x:DataType` on the `DataTemplate` for compiled bindings.
